const jid = $('📋 Normalizar Payload').item.json.remoteJid;
const instancia = $('📋 Normalizar Payload').item.json.instance;
const agora = Date.now();
const JANELA_MS = 60 * 1000;
const MAX_MSGS = 10;

const conversation = $('📋 Normalizar Payload').item.json.conversation || '';

let rateLimitData;
try { rateLimitData = $input.item.json; } catch (e) { rateLimitData = null; }

let contador = rateLimitData?.contador || 0;
let janela_inicio = rateLimitData?.janela_inicio ? new Date(rateLimitData.janela_inicio).getTime() : agora;
let violacoes = rateLimitData?.violacoes || 0;

if ((agora - janela_inicio) > JANELA_MS) {
  contador = 0;
  janela_inicio = agora;
  violacoes = 0;
}

contador += 1;
const bloqueado = contador > MAX_MSGS;
if (bloqueado) violacoes += 1;

return {
  jid, instancia, contador,
  janela_inicio: new Date(janela_inicio).toISOString(),
  violacoes, bloqueado,
  deve_prosseguir: !bloqueado,
  conversation
};

const jid = $('📋 Normalizar Payload').item.json.remoteJid;
const instancia = $('📋 Normalizar Payload').item.json.instance;
const raw = $('🔐 C3: Rate Limit').item.json?.conversation || $('📋 Normalizar Payload').item.json.conversation || '';
const mensagem = String(raw || '');

if (mensagem.length > 2000) {
  return { bloqueado: true, tipo_violacao: 'TAMANHO_EXCEDIDO', jid, instancia,
    payload_resumido: mensagem.substring(0, 200),
    mensagem_usuario: 'Mensagem muito longa. Por favor, seja mais breve.',
    conversation: mensagem, deve_prosseguir: false };
}

const normalizar = (str) => str.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const norm = normalizar(mensagem);
const padroes = [
  { regex: /ignore\s*(as)?\s instru/i, label: 'INJECTION_IGNORE' },
  { regex: /esqueca\s (as)?\s instru/i, label: 'INJECTION_ESQUECA' },
  { regex: /revel[ae]\s (o)?\s*(seu)?\s*(prompt|system)/i, label: 'INJECTION_REVELAR' },
  { regex: /voce\s e\s (agora|um)\s*(root|admin|hacker|gpt|claude)/i, label: 'INJECTION_ROLEPLAY' },
  { regex: /\b(DROP|DELETE|INSERT|UPDATE|SELECT)\s+/i, label: 'INJECTION_SQL' },
  { regex: /act\s as|jailbreak|dan\s mode|developer\s mode/i, label: 'INJECTION_JAILBREAK' },
  { regex: /novo\s prompt|ignore\s tudo|finja\s que|pretenda\s ser/i, label: 'INJECTION_FINJA' }
];

for (const p of padroes) {
  if (p.regex.test(norm)) {
    return { bloqueado: true, tipo_violacao: p.label, jid, instancia,
      payload_resumido: mensagem.substring(0, 200),
      mensagem_usuario: 'Não consigo processar essa mensagem.',
      conversation: mensagem, deve_prosseguir: false };
  }
}

return { bloqueado: false, tipo_violacao: null, jid, instancia,
  mensagem_limpa: mensagem, conversation: mensagem, deve_prosseguir: true };

const professor = $input.item.json;
const agora = new Date();

const professor_existe = !!(professor.id || professor.telefone);

if (!professor_existe) {
  return {
    professor_existe: false,
    acesso_liberado: false,
    status_assinatura: null,
    professor_nome: $('📋 Normalizar Payload').item.json.pushName,
    professor
  };
}

const status = professor.status_assinatura || 'bloqueado';
const professor_nome = professor.nome || $('📋 Normalizar Payload').item.json.pushName;

let acesso_liberado = false;
let trial_expirado = false;

if (status === 'trial') {
  const trialExpira = professor.trial_expira_em ? new Date(professor.trial_expira_em) : null;
  if (trialExpira && trialExpira >= agora) {
    acesso_liberado = true;
  } else {
    trial_expirado = true;
    acesso_liberado = false;
  }
} else if (status === 'ativo') {
  acesso_liberado = true;
} else if (status === 'atrasado') {
  const dataVenc = professor.data_vencimento ? new Date(professor.data_vencimento) : null;
  const diasAtraso = dataVenc ? Math.floor((agora - dataVenc) / (1000 * 60 * 60 * 24)) : 99;
  acesso_liberado = diasAtraso <= 3;
} else {
  acesso_liberado = false;
}

return {
  professor_existe,
  acesso_liberado,
  status_assinatura: trial_expirado ? 'bloqueado' : status,
  professor_nome,
  data_vencimento: professor.data_vencimento,
  trial_expira_em: professor.trial_expira_em,
  stripe_customer_id: professor.stripe_customer_id,
  professor
};

