const msg = $('📋 Normalizar Payload').item.json.conversation || '';
const norm = msg.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

// ─── CÓDIGO BNCC → PLANO ───
const codigoBNCC = /\b(EF|EM)\d{2}[A-Z]{2,3}\d{2,3}\b/i;
if (codigoBNCC.test(msg)) {
  return { intencao: 'plano_aula', confianca: 0.98, motivo: 'codigo_bncc_detectado', deve_prosseguir: true, conversation: msg };
}

// ─── ROTINA SEMANAL ───
const rotinaKeywords = /\b(rotina|rotina semanal|planejamento semanal|grade horaria|horario de aulas|semana de aulas|rotin)\b/i;
if (rotinaKeywords.test(norm)) {
  return { intencao: 'rotina', confianca: 0.95, motivo: 'keyword_rotina', deve_prosseguir: true, conversation: msg };
}

// ─── RESPOSTA PÓS-PLANO ───
const respostaPosPlano = /^(sim|s|yes|quero|pode|claro|com certeza|manda|vai|top|ok|otimo|por favor|pfv|pf|obrigad|valeu|show|legal|gostei|dica|dicas|me da|me manda)[\s!?.]?$/i;
if (respostaPosPlano.test(norm)) {
  return { intencao: 'pos_plano', confianca: 0.95, motivo: 'resposta_curta_pos_plano', deve_prosseguir: true, conversation: msg };
}

// ─── SAUDAÇÕES PURAS ───
if (/^(oi|ola|bom dia|boa tarde|boa noite|tudo bem|tudo bom|hello|hi|eai|e ai|hey)[\s!?.]?$/.test(norm)) {
  return { intencao: 'chat', confianca: 0.99, motivo: 'saudacao_pura', deve_prosseguir: true, conversation: msg };
}

// ─── PLANO DE AULA (antes de atividade, protege "plano com atividade") ───
const planoExplicito = /plano\s(de\s*)?(aula|semanal|aulas)|planejamento\s*(semanal|de\s aula|da\s semana)|planejar\s*(a\s*)?aula/i;
const verbosCriacao = /(criar|gerar|fazer|montar|preparar|elaborar|preciso\s de|quero|me\s (ajuda|faz|gera|cria|monta))\s*(um\s*)?(plano|aula|sequencia|roteiro|planejamento)/i;
const temSerie = /\b(\d+[°º\u00B0]?\s*(ano|serie)|[1-3][aª]\s serie|ensino\s medio|fund(amental)?\s*[12]|ef\s*\d|em\s*\d)\b/i;
const temDisciplina = /\b(matematica|portugues|historia|geografia|ciencias|biologia|fisica|quimica|ingles|arte|educacao\s fisica|filosofia|sociologia|lingua\s portuguesa|literatura|redacao|alfabetizacao)\b/i;
const padraoEstruturado = temSerie.test(norm) && temDisciplina.test(norm);
const temSemana = /semana|proxima\s semana|\d{1,2}\/\d{1,2}|segunda|terca|quarta|quinta|sexta/i;
const padraoSemana = temSemana.test(norm) && temDisciplina.test(norm);
const frasesProfessor = /preciso\s(de\s*)?(um\s*)?(plano|aula)|me\s ajuda\s(com|a|no|na)|o\s que\s(posso|devo)\s*(ensinar|trabalhar|dar)|tema\s*(para|de)\s*(aula|hoje|amanha)|conteudo\s*(para|de)\s aula|montar\s(uma\s*)?aula|fazer\s*(uma\s*)?aula/i;

if (planoExplicito.test(norm) || verbosCriacao.test(norm) || padraoEstruturado || padraoSemana || frasesProfessor.test(norm)) {
  return { intencao: 'plano_aula', confianca: 0.92, motivo: 'intencao_plano_detectada', deve_prosseguir: true, conversation: msg };
}

// ─── ATIVIDADE ILUSTRADA → FORM (absorve o antigo "material de apoio") ───
const atividadeKeywords = /\b(atividade|exercicio|exercicios|lista|prova|avaliacao|questao|questoes|material|apoio|imprimir)\b/i;
if (atividadeKeywords.test(norm)) {
  return { intencao: 'atividade_ilustrada', confianca: 0.93, motivo: 'keyword_atividade_form', deve_prosseguir: true, conversation: msg };
}

// ─── DICAS PEDAGÓGICAS ───
const dicasKeywords = /^dicas?[\s!?.]?$|dica\s*(de\s*)?(ensino|aula|pedagogia|didatica)|como\s*(ensinar|trabalhar|abordar|explicar)/i;
if (dicasKeywords.test(norm)) {
  return { intencao: 'chat', confianca: 0.90, motivo: 'keyword_dicas', deve_prosseguir: true, conversation: msg };
}

// ─── FORA DE ESCOPO ───
const foraEscopo = /\b(novela|politica partidaria|receita culinaria|moda|celebridade|fofoca|bitcoin|bolsa de valores)\b/i;
if (foraEscopo.test(norm)) {
  return { intencao: 'fora_de_escopo', confianca: 0.85, motivo: 'topico_nao_pedagogico', deve_prosseguir: false, conversation: msg };
}

// ─── DEFAULT ─
return { intencao: 'chat', confianca: 0.75, motivo: 'default_chat_pedagogico', deve_prosseguir: true, conversation: msg };

const msg = $('📋 Normalizar Payload').item.json.conversation;
const nome = $('⚙️ Checar Status').item.json.professor_nome || $('📋 Normalizar Payload').item.json.pushName;
const instancia = $('📋 Normalizar Payload').first().json.instance;
const contato = $('📋 Normalizar Payload').first().json.remoteJid;
