let raw = '';
try { raw = raw || $('Chamar: Plano Form Trigger').item?.json?.output || ''; } catch(e) {}
try { raw = raw || $('Chamar: Gerador de Rotina (WF1)').item?.json?.output || ''; } catch(e) {}
try { raw = raw || $('Agente Chat Pedagógico').item?.json?.output || ''; } catch(e) {}
try { raw = raw || $input.item.json?.output || ''; } catch(e) {}

let sanitizado = String(raw);
const patterns = [/<system>[\s\S]*?<\/system>/gi, /\[INST\][\s\S]*?\[\/INST\]/gi, /<<SYS>>[\s\S]*?<\/SYS>>/gi];
for (const p of patterns) sanitizado = sanitizado.replace(p, '');

const urlRegex = /https?:\/\/([\w\-.]+)(\/[^\s]*)?/gi;
sanitizado = sanitizado.replace(urlRegex, (match, domain) => {
  const permitidos = ['google.com', 'docs.google.com', 'drive.google.com', 'n8n.docenteia.com.br', 'docenteia.com.br'];
  return permitidos.some(d => domain.endsWith(d)) ? match : '[link removido]';
});

if (sanitizado.length > 4000) sanitizado = sanitizado.substring(0, 3997) + '...';
return { output_sanitizado: sanitizado.trim() };
